=== FILE: apb_regs.v ===
// apb_regs: four 32-bit read/write registers behind an APB4 completer port.
// Implements microarchitecture.md for interface_spec.md (apb_regs).
//   * Zero wait states: pready tied high (uarch 1).
//   * access = psel && penable is the completing cycle (uarch 1).
//   * Four separate flops, strobed byte merge, index paddr[3:2] (uarch 2).
//   * mapped = word aligned and paddr >> 4 == 0 (uarch 3, ispec 5).
//   * pslverr = access && !mapped (uarch 3).
//   * prdata: combinational mux, zero unless a mapped read access (uarch 4).
//   * presetn: synchronous, active low, all registers to zero (uarch 5).
`default_nettype none

module apb_regs #(
    parameter integer ADDR_WIDTH = 8,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    pclk,
    input  wire                    presetn,
    input  wire [ADDR_WIDTH-1:0]   paddr,
    input  wire                    psel,
    input  wire                    penable,
    input  wire                    pwrite,
    input  wire [DATA_WIDTH-1:0]   pwdata,
    input  wire [DATA_WIDTH/8-1:0] pstrb,
    output wire [DATA_WIDTH-1:0]   prdata,
    output wire                    pready,
    output wire                    pslverr
);

  localparam integer NBYTES = DATA_WIDTH / 8;

  wire                  access;
  wire                  mapped;
  wire                  wr_access;
  wire                  rd_access;
  wire [1:0]            idx;
  wire [DATA_WIDTH-1:0] wmask;
  wire                  we0;
  wire                  we1;
  wire                  we2;
  wire                  we3;
  wire [DATA_WIDTH-1:0] nxt0;
  wire [DATA_WIDTH-1:0] nxt1;
  wire [DATA_WIDTH-1:0] nxt2;
  wire [DATA_WIDTH-1:0] nxt3;

  reg  [DATA_WIDTH-1:0] reg0;
  reg  [DATA_WIDTH-1:0] reg1;
  reg  [DATA_WIDTH-1:0] reg2;
  reg  [DATA_WIDTH-1:0] reg3;
  reg  [DATA_WIDTH-1:0] rd_mux;

  // Completing cycle: pready is always high, so access is the completion.
  assign access    = psel & penable;

  // Address decode: word aligned and inside 0x0 to 0xC.
  assign mapped    = (paddr[1:0] == 2'b00) &&
                     (paddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});

  assign wr_access = access & pwrite & mapped;
  assign rd_access = access & ~pwrite & mapped;
  assign idx       = paddr[3:2];

  // Byte-lane write mask from the strobes: bit n enables bits 8n+7:8n.
  genvar g;
  generate
    for (g = 0; g < NBYTES; g = g + 1) begin : g_wmask
      assign wmask[8*g +: 8] = {8{pstrb[g]}};
    end
  endgenerate

  // merge(old, data, strb): strobed bytes from pwdata, others kept.
  assign nxt0 = (reg0 & ~wmask) | (pwdata & wmask);
  assign nxt1 = (reg1 & ~wmask) | (pwdata & wmask);
  assign nxt2 = (reg2 & ~wmask) | (pwdata & wmask);
  assign nxt3 = (reg3 & ~wmask) | (pwdata & wmask);

  assign we0 = wr_access && (idx == 2'd0);
  assign we1 = wr_access && (idx == 2'd1);
  assign we2 = wr_access && (idx == 2'd2);
  assign we3 = wr_access && (idx == 2'd3);

  // Register file: synchronous active-low reset, load on a mapped write access.
  always @(posedge pclk) begin
    if (!presetn) begin
      reg0 <= {DATA_WIDTH{1'b0}};
    end else if (we0) begin
      reg0 <= nxt0;
    end
  end

  always @(posedge pclk) begin
    if (!presetn) begin
      reg1 <= {DATA_WIDTH{1'b0}};
    end else if (we1) begin
      reg1 <= nxt1;
    end
  end

  always @(posedge pclk) begin
    if (!presetn) begin
      reg2 <= {DATA_WIDTH{1'b0}};
    end else if (we2) begin
      reg2 <= nxt2;
    end
  end

  always @(posedge pclk) begin
    if (!presetn) begin
      reg3 <= {DATA_WIDTH{1'b0}};
    end else if (we3) begin
      reg3 <= nxt3;
    end
  end

  // Read multiplexer.
  always @* begin
    case (idx)
      2'd0:    rd_mux = reg0;
      2'd1:    rd_mux = reg1;
      2'd2:    rd_mux = reg2;
      2'd3:    rd_mux = reg3;
      default: rd_mux = {DATA_WIDTH{1'b0}};
    endcase
  end

  assign prdata  = rd_access ? rd_mux : {DATA_WIDTH{1'b0}};
  assign pready  = 1'b1;
  assign pslverr = access & ~mapped;

`ifdef FORMAL
  // ---------------------------------------------------------------------
  // Design-intent properties (default parameters: 8-bit address, 32-bit data).
  // The decode and byte merge below are written independently of the design.
  // ---------------------------------------------------------------------
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge pclk)
    f_past_valid <= 1'b1;

  wire f_access = psel && penable;
  wire f_mapped = (paddr <= 8'h0C) && (paddr[1:0] == 2'b00);

  // Requester (manager) rules.
  always @(*) begin
    if (!f_past_valid)
      assume(!presetn);
    if (!presetn)
      assume(!psel);
    if (!psel)
      assume(!penable);
  end

  always @(posedge pclk) begin
    if (f_past_valid) begin
      // penable only in the cycle after a setup phase
      if (penable)
        assume($past(psel) && !$past(penable) && $past(presetn));
      // a setup phase is followed by its access phase, request held stable
      if ($past(presetn) && presetn && $past(psel) && !$past(penable)) begin
        assume(psel && penable);
        assume(paddr  == $past(paddr));
        assume(pwrite == $past(pwrite));
        assume(pwdata == $past(pwdata));
        assume(pstrb  == $past(pstrb));
      end
    end
  end

  // Reference register model.
  function [31:0] f_merge;
    input [31:0] o;
    input [31:0] d;
    input [3:0]  s;
    begin
      f_merge = { (s[3] ? d[31:24] : o[31:24]),
                  (s[2] ? d[23:16] : o[23:16]),
                  (s[1] ? d[15:8]  : o[15:8]),
                  (s[0] ? d[7:0]   : o[7:0]) };
    end
  endfunction

  reg [31:0] f_m0;
  reg [31:0] f_m1;
  reg [31:0] f_m2;
  reg [31:0] f_m3;

  always @(posedge pclk) begin
    if (!presetn) begin
      f_m0 <= 32'h0;
      f_m1 <= 32'h0;
      f_m2 <= 32'h0;
      f_m3 <= 32'h0;
    end else if (f_access && pwrite && f_mapped) begin
      case (paddr)
        8'h00:   f_m0 <= f_merge(f_m0, pwdata, pstrb);
        8'h04:   f_m1 <= f_merge(f_m1, pwdata, pstrb);
        8'h08:   f_m2 <= f_merge(f_m2, pwdata, pstrb);
        8'h0C:   f_m3 <= f_merge(f_m3, pwdata, pstrb);
        default: ;
      endcase
    end
  end

  // Completer rules.
  always @(*) begin
    // zero wait states
    assert(pready);
    // quiet outside the access phase
    if (!f_access) begin
      assert(prdata == 32'h0);
      assert(!pslverr);
    end else begin
      // address policy
      assert(pslverr == !f_mapped);
      if (!f_mapped || pwrite)
        assert(prdata == 32'h0);
    end
    if (f_past_valid) begin
      // registers change only by a mapped strobed write, to the written bytes
      assert(reg0 == f_m0);
      assert(reg1 == f_m1);
      assert(reg2 == f_m2);
      assert(reg3 == f_m3);
      // a mapped read returns the modelled register
      if (f_access && !pwrite) begin
        case (paddr)
          8'h00:   assert(prdata == f_m0);
          8'h04:   assert(prdata == f_m1);
          8'h08:   assert(prdata == f_m2);
          8'h0C:   assert(prdata == f_m3);
          default: assert(prdata == 32'h0);
        endcase
      end
    end
  end

  // Registers are zero after reset.
  always @(posedge pclk) begin
    if (f_past_valid && !$past(presetn)) begin
      assert(reg0 == 32'h0);
      assert(reg1 == 32'h0);
      assert(reg2 == 32'h0);
      assert(reg3 == 32'h0);
    end
  end

  // Covers: the proof is not empty.
  always @(posedge pclk) begin
    if (f_past_valid && presetn) begin
      cover(f_access && pwrite && f_mapped && (pstrb == 4'b0101));
      cover(f_access && !pwrite && (paddr == 8'h00) && (prdata != 32'h0));
      cover(f_access && !pwrite && (paddr == 8'h04) && (prdata != 32'h0));
      cover(f_access && !pwrite && (paddr == 8'h08) && (prdata != 32'h0));
      cover(f_access && !pwrite && (paddr == 8'h0C) && (prdata != 32'h0));
      cover(f_access && pwrite && pslverr);
      cover(f_access && !pwrite && pslverr);
      cover($past(f_access) && psel && !penable);
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_regs_tb.v ===
// apb_regs_tb: self-checking directed testbench for apb_regs.
// Inputs are driven just after the falling edge; outputs are checked 1 ns
// later, well before the next rising edge, so there is no race with the DUT.
`timescale 1ns/1ps
`default_nettype none

module apb_regs_tb;

  reg         pclk = 1'b0;
  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel;
  reg         penable;
  reg         pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  wire [31:0] prdata;
  wire        pready;
  wire        pslverr;

  integer passed;
  integer failed;
  reg [8*64-1:0] nonce;

  // Shadow model of the four registers.
  reg [31:0] model [0:3];

  apb_regs #(
      .ADDR_WIDTH(8),
      .DATA_WIDTH(32)
  ) dut (
      .pclk    (pclk),
      .presetn (presetn),
      .paddr   (paddr),
      .psel    (psel),
      .penable (penable),
      .pwrite  (pwrite),
      .pwdata  (pwdata),
      .pstrb   (pstrb),
      .prdata  (prdata),
      .pready  (pready),
      .pslverr (pslverr)
  );

  always #5 pclk = ~pclk;

  // ----------------------------------------------------------------------
  // Reference functions (from interface_spec.md sections 3 and 5)
  // ----------------------------------------------------------------------
  function tb_mapped;
    input [7:0] a;
    begin
      tb_mapped = (a[1:0] == 2'b00) && (a < 8'h10);
    end
  endfunction

  function [31:0] tb_merge;
    input [31:0] old_v;
    input [31:0] new_v;
    input [3:0]  strb;
    begin
      tb_merge = { (strb[3] ? new_v[31:24] : old_v[31:24]),
                   (strb[2] ? new_v[23:16] : old_v[23:16]),
                   (strb[1] ? new_v[15:8]  : old_v[15:8]),
                   (strb[0] ? new_v[7:0]   : old_v[7:0]) };
    end
  endfunction

  // ----------------------------------------------------------------------
  // Checks
  // ----------------------------------------------------------------------
  // Outside the access phase prdata and pslverr are zero.
  task check_quiet;
    begin
      if (prdata === 32'h0) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("quiet: prdata=%h (expected 0) psel=%b penable=%b at %0t",
               prdata, psel, penable, $time);
      end
      if (pslverr === 1'b0) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("quiet: pslverr=%b (expected 0) psel=%b penable=%b at %0t",
               pslverr, psel, penable, $time);
      end
    end
  endtask

  // In the access phase: zero wait states, response by the address policy.
  task check_access;
    input        exp_err;
    input [31:0] exp_data;
    begin
      if (pready === 1'b1) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("wait state: pready=%b addr=%h at %0t", pready, paddr, $time);
      end
      if (pslverr === exp_err) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("pslverr=%b expected %b addr=%h pwrite=%b at %0t",
               pslverr, exp_err, paddr, pwrite, $time);
      end
      if (prdata === exp_data) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("prdata=%h expected %h addr=%h pwrite=%b at %0t",
               prdata, exp_data, paddr, pwrite, $time);
      end
    end
  endtask

  // ----------------------------------------------------------------------
  // Bus operations
  // ----------------------------------------------------------------------
  task idle;
    input integer cycles;
    integer k;
    begin
      for (k = 0; k < cycles; k = k + 1) begin
        @(negedge pclk);
        psel    = 1'b0;
        penable = 1'b0;
        pwrite  = 1'b0;
        paddr   = 8'h00;
        pwdata  = 32'h0;
        pstrb   = 4'h0;
        #1;
        check_quiet;
      end
    end
  endtask

  task apb_write;
    input [7:0]  addr;
    input [31:0] data;
    input [3:0]  strb;
    reg          exp_err;
    begin
      exp_err = ~tb_mapped(addr);
      // setup phase
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = 1'b1;
      paddr   = addr;
      pwdata  = data;
      pstrb   = strb;
      #1;
      check_quiet;
      // access phase (one cycle: zero wait states)
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check_access(exp_err, 32'h0);
      // the write takes effect on the rising edge that ends this access
      if (!exp_err)
        model[addr[3:2]] = tb_merge(model[addr[3:2]], data, strb);
    end
  endtask

  task apb_read;
    input [7:0] addr;
    reg         exp_err;
    reg  [31:0] exp_data;
    begin
      exp_err  = ~tb_mapped(addr);
      exp_data = exp_err ? 32'h0 : model[addr[3:2]];
      // setup phase
      @(negedge pclk);
      psel    = 1'b1;
      penable = 1'b0;
      pwrite  = 1'b0;
      paddr   = addr;
      pwdata  = 32'hBAD0_BAD0;
      pstrb   = 4'h0;
      #1;
      check_quiet;
      // access phase
      @(negedge pclk);
      penable = 1'b1;
      #1;
      check_access(exp_err, exp_data);
    end
  endtask

  task do_reset;
    input integer cycles;
    integer k;
    begin
      @(negedge pclk);
      presetn = 1'b0;
      psel    = 1'b0;
      penable = 1'b0;
      pwrite  = 1'b0;
      paddr   = 8'h00;
      pwdata  = 32'h0;
      pstrb   = 4'h0;
      #1;
      check_quiet;
      for (k = 1; k < cycles; k = k + 1) begin
        @(negedge pclk);
        #1;
        check_quiet;
      end
      @(negedge pclk);
      presetn = 1'b1;
      #1;
      check_quiet;
      model[0] = 32'h0;
      model[1] = 32'h0;
      model[2] = 32'h0;
      model[3] = 32'h0;
    end
  endtask

  // ----------------------------------------------------------------------
  // Watchdog: a hung test ends without a verdict, which is a failed run.
  // ----------------------------------------------------------------------
  initial begin
    #2000000;
    $error("watchdog timeout at %0t", $time);
    $finish;
  end

  // ----------------------------------------------------------------------
  // Test sequence
  // ----------------------------------------------------------------------
  initial begin : main
    integer    a;
    integer    r;
    integer    s;
    reg [31:0] d;

    passed = 0;
    failed = 0;
    nonce  = {(8*64){1'b0}};
    if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0)
      nonce = {(8*64){1'b0}};

    presetn = 1'b0;
    psel    = 1'b0;
    penable = 1'b0;
    pwrite  = 1'b0;
    paddr   = 8'h00;
    pwdata  = 32'h0;
    pstrb   = 4'h0;
    model[0] = 32'h0;
    model[1] = 32'h0;
    model[2] = 32'h0;
    model[3] = 32'h0;

    // 1. Reset and reset values
    do_reset(3);
    idle(2);
    apb_read(8'h00);
    apb_read(8'h04);
    apb_read(8'h08);
    apb_read(8'h0C);
    idle(1);

    // 2. Full-word write then read of every register, back to back
    apb_write(8'h00, 32'h0123_4567, 4'hF);
    apb_write(8'h04, 32'h89AB_CDEF, 4'hF);
    apb_write(8'h08, 32'hDEAD_BEEF, 4'hF);
    apb_write(8'h0C, 32'hCAFE_F00D, 4'hF);
    apb_read(8'h00);
    apb_read(8'h04);
    apb_read(8'h08);
    apb_read(8'h0C);

    // 3. Idle gaps between transfers, and write followed directly by read
    idle(3);
    apb_write(8'h04, 32'h5555_AAAA, 4'hF);
    idle(1);
    apb_read(8'h04);
    idle(2);
    apb_write(8'h0C, 32'h0F0F_F0F0, 4'hF);
    apb_read(8'h0C);
    idle(4);
    apb_read(8'h00);
    apb_write(8'h08, 32'h1111_2222, 4'hF);
    apb_write(8'h00, 32'h3333_4444, 4'hF);
    apb_read(8'h08);
    apb_read(8'h00);
    idle(1);

    // 4. pstrb partial writes: every strobe pattern on every register
    for (r = 0; r < 4; r = r + 1) begin
      apb_write({r[5:0], 2'b00}, 32'hFFFF_FFFF, 4'hF);
      apb_read({r[5:0], 2'b00});
      for (s = 0; s < 16; s = s + 1) begin
        d = 32'h1234_5678 ^ {8{s[3:0]}} ^ {4{r[7:0]}};
        apb_write({r[5:0], 2'b00}, d, s[3:0]);
        apb_read({r[5:0], 2'b00});
      end
      idle(1);
    end

    // 5. PSLVERR policy: misaligned and out-of-range addresses
    apb_write(8'h00, 32'hA0A0_A0A0, 4'hF);
    apb_write(8'h04, 32'hB1B1_B1B1, 4'hF);
    apb_write(8'h08, 32'hC2C2_C2C2, 4'hF);
    apb_write(8'h0C, 32'hD3D3_D3D3, 4'hF);
    idle(1);
    for (a = 0; a < 256; a = a + 1) begin
      if (!tb_mapped(a[7:0]))
        apb_write(a[7:0], 32'h5A5A_0000 | a, 4'hF);
    end
    apb_write(8'h10, 32'hFFFF_FFFF, 4'h0);
    apb_write(8'h01, 32'hFFFF_FFFF, 4'h3);
    apb_write(8'h0E, 32'hFFFF_FFFF, 4'hC);
    idle(2);
    // registers unchanged by the unmapped writes
    apb_read(8'h00);
    apb_read(8'h04);
    apb_read(8'h08);
    apb_read(8'h0C);
    // read sweep of the whole 256-byte slot
    for (a = 0; a < 256; a = a + 1)
      apb_read(a[7:0]);
    idle(2);

    // 6. Reset again, after traffic
    apb_write(8'h00, 32'hFEED_0000, 4'hF);
    apb_write(8'h04, 32'hFEED_0001, 4'hF);
    apb_write(8'h08, 32'hFEED_0002, 4'hF);
    apb_write(8'h0C, 32'hFEED_0003, 4'hF);
    apb_read(8'h0C);
    do_reset(2);
    apb_read(8'h00);
    apb_read(8'h04);
    apb_read(8'h08);
    apb_read(8'h0C);
    idle(2);

    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

